#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_current_mode: Mutex<Option<open_platform_Data_Model::OperatingMode>> = Mutex::new(None);
  pub static ref IN_EthernetFramesRxIn0: Mutex<Option<open_platform_Data_Model::RawEthernetMessage>> = Mutex::new(None);
  pub static ref IN_EthernetFramesRxIn1: Mutex<Option<open_platform_Data_Model::RawEthernetMessage>> = Mutex::new(None);
  pub static ref IN_EthernetFramesRxIn2: Mutex<Option<open_platform_Data_Model::RawEthernetMessage>> = Mutex::new(None);
  pub static ref IN_EthernetFramesRxIn3: Mutex<Option<open_platform_Data_Model::RawEthernetMessage>> = Mutex::new(None);
  pub static ref OUT_EthernetFramesRxOut0: Mutex<Option<open_platform_Data_Model::RawEthernetMessage>> = Mutex::new(None);
  pub static ref OUT_EthernetFramesRxOut1: Mutex<Option<open_platform_Data_Model::RawEthernetMessage>> = Mutex::new(None);
  pub static ref OUT_EthernetFramesRxOut2: Mutex<Option<open_platform_Data_Model::RawEthernetMessage>> = Mutex::new(None);
  pub static ref OUT_EthernetFramesRxOut3: Mutex<Option<open_platform_Data_Model::RawEthernetMessage>> = Mutex::new(None);
  pub static ref OUT_MAVLinkFramesRxOut0: Mutex<Option<open_platform_Data_Model::MAVLinkUDPMessage_Impl>> = Mutex::new(None);
  pub static ref OUT_MAVLinkFramesRxOut1: Mutex<Option<open_platform_Data_Model::MAVLinkUDPMessage_Impl>> = Mutex::new(None);
  pub static ref OUT_MAVLinkFramesRxOut2: Mutex<Option<open_platform_Data_Model::MAVLinkUDPMessage_Impl>> = Mutex::new(None);
  pub static ref OUT_MAVLinkFramesRxOut3: Mutex<Option<open_platform_Data_Model::MAVLinkUDPMessage_Impl>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_current_mode.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_EthernetFramesRxIn0.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_EthernetFramesRxIn1.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_EthernetFramesRxIn2.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_EthernetFramesRxIn3.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_EthernetFramesRxOut0.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_EthernetFramesRxOut1.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_EthernetFramesRxOut2.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_EthernetFramesRxOut3.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_MAVLinkFramesRxOut0.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_MAVLinkFramesRxOut1.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_MAVLinkFramesRxOut2.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_MAVLinkFramesRxOut3.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_current_mode(value: *mut open_platform_Data_Model::OperatingMode) -> bool
{
  unsafe {
    let guard = IN_current_mode.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

